    totalRevenue: data.totalRevenue || 0,
    totalSubtotal: data.totalSubtotalRevenue || data.netRevenue || 0,
    totalCost: data.totalCost || 0,
    grossMargin: data.grossMargin || 0,
    grossMarginPct: data.grossMarginPct || 0,
